-- ============================================================
-- spell_proc: Backlash no longer procs at all
-- ============================================================
-- The core ships an all-ranks row (-34935) from when Backlash was a
-- PROC_TRIGGER_SPELL talent.  Backlash is now a SCHOOL_ABSORB, so the row is
-- dead weight -- and because its ProcFlags is 0 it falls back to the spell's
-- DBC ProcFlags (also now 0), which logs "proc will not be triggered" on
-- every startup.  Drop it.  ABS() is required to match the negative id.
DELETE FROM `spell_proc` WHERE ABS(`SpellId`) IN (34935, 34938, 34939);

